initJs:
function(container, apiUrl, tables) {
  // 予測結果データを保持する変数
  let currentPredictionResults = [];

  // 店舗データを店舗選択に設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの再描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#prediction-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.予測結果ID}">
        <td>${r.商品コード || ''}</td>
        <td>${r.商品名 || ''}</td>
        <td>${r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : ''}</td>
        <td>${r.予測数量 || 0}</td>
        <td>${r.予測精度 || 0}%</td>
        <td>${r.推奨発注数量 || 0}</td>
        <td>${r.実績数量 || '-'}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 0.8em; 
                       background: ${r.予測ステータス === '完了' ? 'rgba(34, 197, 94, 0.1)' : 
                                   r.予測ステータス === '算出中' ? 'rgba(59, 130, 246, 0.1)' : 
                                   'rgba(239, 68, 68, 0.1)'};
                       color: ${r.予測ステータス === '完了' ? '#22c55e' : 
                               r.予測ステータス === '算出中' ? '#3b82f6' : '#ef4444'};">
            ${r.予測ステータス || '未実行'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // 予測グラフの描画
  function drawPredictionChart(results) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!results || results.length === 0) return;

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの準備
    const maxValue = Math.max(...results.map(r => Math.max(r.予測数量 || 0, r.実績数量 || 0)));
    const minValue = 0;
    const valueRange = maxValue - minValue;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // グリッドライン
    ctx.strokeStyle = '#2d3748';
    ctx.lineWidth = 0.5;
    for (let i = 1; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 予測データの描画
    if (results.length > 1) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();
      results.forEach((r, i) => {
        const x = padding + (chartWidth / (results.length - 1)) * i;
        const y = padding + chartHeight - ((r.予測数量 || 0) / maxValue) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 実績データの描画（存在する場合）
      const hasActual = results.some(r => r.実績数量);
      if (hasActual) {
        ctx.strokeStyle = '#ef4444';
        ctx.lineWidth = 2;
        ctx.beginPath();
        results.forEach((r, i) => {
          if (r.実績数量) {
            const x = padding + (chartWidth / (results.length - 1)) * i;
            const y = padding + chartHeight - (r.実績数量 / maxValue) * chartHeight;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
          }
        });
        ctx.stroke();
      }
    }

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding + 10, 20);
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(padding + 50, 12, 15, 2);

    if (results.some(r => r.実績数量)) {
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText('実績値', padding + 80, 20);
      ctx.fillStyle = '#ef4444';
      ctx.fillRect(padding + 120, 12, 15, 2);
    }
  }

  // バリデーション
  function validatePredictionForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }
    if (!category) {
      alert('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate) {
      alert('予測期間の開始日を設定してください');
      return false;
    }
    if (!endDate) {
      alert('予測期間の終了日を設定してください');
      return false;
    }
    if (!model) {
      alert('予測モデルを選択してください');
      return false;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (start < today) {
      alert('開始日は現在日以降の日付を設定してください');
      return false;
    }
    if (start >= end) {
      alert('開始日は終了日より前の日付を入力してください');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    if (!validatePredictionForm()) return;

    const overlay = container.querySelector('#processing-overlay');
    overlay.classList.remove('hidden');

    try {
      // 予測条件の取得
      const storeId = container.querySelector('#store-select').value;
      const category = container.querySelector('#category-select').value;
      const startDate = container.querySelector('#start-date').value;
      const endDate = container.querySelector('#end-date').value;
      const model = container.querySelector('#model-select').value;
      const seasonal = container.querySelector('#seasonal-factor').checked;
      const event = container.querySelector('#event-factor').checked;
      const weather = container.querySelector('#weather-factor').checked;

      // 模擬的な予測処理（実際のAI処理をシミュレート）
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 商品マスタから対象商品を取得
      const productTable = tables.find(t => t.tableName === '商品マスタ');
      const targetProducts = productTable?.records?.filter(p => 
        p.商品カテゴリID === category && p.AI予測対象フラグ
      ) || [];

      // 予測結果データの生成
      const predictions = [];
      const start = new Date(startDate);
      const end = new Date(endDate);
      const daysDiff = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1;

      for (let product of targetProducts.slice(0, 5)) { // 最大5商品
        for (let i = 0; i < Math.min(daysDiff, 30); i++) { // 最大30日
          const targetDate = new Date(start);
          targetDate.setDate(start.getDate() + i);

          const baseQuantity = Math.floor(Math.random() * 50) + 20;
          const seasonalFactor = seasonal ? (Math.sin(i * 0.2) * 0.1 + 1) : 1;
          const weatherFactor = weather ? (Math.random() * 0.2 + 0.9) : 1;
          const eventFactor = event ? (Math.random() > 0.8 ? 1.3 : 1) : 1;

          const predictedQuantity = Math.floor(baseQuantity * seasonalFactor * weatherFactor * eventFactor);
          const accuracy = Math.floor(Math.random() * 20) + 75; // 75-95%

          const prediction = {
            予測結果ID: `pred-${Date.now()}-${i}`,
            店舗ID: storeId,
            商品ID: product.商品ID,
            商品コード: product.商品コード,
            商品名: product.商品名,
            予測対象日: targetDate.toISOString(),
            予測数量: predictedQuantity,
            予測精度: accuracy,
            推奨発注数量: Math.ceil(predictedQuantity * 1.1),
            予測モデルバージョン: model,
            実績数量: Math.random() > 0.7 ? Math.floor(predictedQuantity * (0.8 + Math.random() * 0.4)) : null,
            予測ステータス: '完了',
            発注済フラグ: false,
            作成日時: new Date().toISOString()
          };

          predictions.push(prediction);

          // 需要予測結果テーブルに保存
          await window.aivicApi.save(6, prediction); // 需要予測結果は6番目のテーブル
        }
      }

      currentPredictionResults = predictions;

      // 結果表示
      container.querySelector('#prediction-results').classList.remove('hidden');
      container.querySelector('#product-prediction-list').classList.remove('hidden');

      // 精度指標の更新
      const avgAccuracy = predictions.reduce((sum, p) => sum + p.予測精度, 0) / predictions.length;
      container.querySelector('#accuracy-value').textContent = `${Math.round(avgAccuracy)}%`;
      container.querySelector('#confidence-interval').textContent = `±${Math.round(avgAccuracy * 0.1)}%`;
      container.querySelector('#mape-value').textContent = `${Math.round((100 - avgAccuracy) * 0.5)}%`;
      container.querySelector('#r2-value').textContent = `0.${Math.floor(avgAccuracy)}`;

      // グラフとテーブルの描画
      drawPredictionChart(predictions.slice(0, 10)); // 最初の10件をグラフ表示
      renderPredictionResults(predictions);

    } catch (error) {
      console.error('予測実行エラー:', error);
      alert('予測実行中にエラーが発生しました');
    } finally {
      overlay.classList.add('hidden');
    }
  }

  // CSVエクスポート
  function exportPredictionResults() {
    if (currentPredictionResults.length === 0) {
      alert('エクスポートする予測結果がありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '予測精度', '推奨発注数量', '実績数量', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentPredictionResults.map(r => [
        r.商品コード || '',
        `"${r.商品名 || ''}"`,
        r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : '',
        r.予測数量 || 0,
        `${r.予測精度 || 0}%`,
        r.推奨発注数量 || 0,
        r.実績数量 || '',
        r.予測ステータス || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(today.getDate() + 7);

  container.querySelector('#start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);
  container.querySelector('#btn-export').addEventListener('click', exportPredictionResults);
}
